#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-09-10
/**
 * Every versioned manifest inside the build-drift roster must be stamped (#4038).
 *
 * THE INVARIANT
 *
 *   If a tracked file carries a `version` AND sits inside ci.yml's build-drift
 *   roster, release-please must stamp it via `extra-files`.
 *
 * Break it and every release PR fails the required Build check on drift, because
 * release-please bumps the source, the mirror regenerates from it during the
 * next build, and release-please does not run a build. The Skill Build Autoheal
 * bot then pushes a second commit and the release lands anyway, which is exactly
 * why this survived: the END STATE is green, so nobody reads the intermediate
 * red. beta.13 needed `9cc19029`, beta.14 needed `50b86d3b` then `430b1ca0`.
 *
 * WHY THE RULE IS PHRASED AROUND THE DRIFT ROSTER
 *
 * "Every versioned plugin.json must be in extra-files" would be wrong. It would
 * demand stamping `tests/fixtures/fn-hooks-canary/.claude-plugin/plugin.json`,
 * which is pinned at 0.0.1 on purpose: it is a fixture asserting an upstream
 * shape, never shipped, and stamping it would destroy what it tests.
 *
 * Tying the rule to the roster gets that right for a reason rather than by an
 * allowlist: a file outside the roster can be stale without failing anything, so
 * nothing forces it to be stamped. Fixtures fall out naturally, and no
 * exemption list has to be maintained (an exemption list is the thing that goes
 * stale and re-creates this bug a fourth time).
 *
 * SECOND RECURRENCE
 *
 * `docs/audits/release-please-version-drift-2026-05-22.md` is the same class.
 * The two Codex SOURCE manifests joined `extra-files` on 2026-09-06 (#2528)
 * after sitting at 9.5.4 for 40 releases because nothing stamped them. That fix
 * reached the sources and stopped short of the mirrors. This test is the part
 * that makes a third instance impossible rather than merely unlikely.
 */
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const CONFIG = join(REPO_ROOT, '.release-please-config.json');
const CI = join(REPO_ROOT, '.github', 'workflows', 'ci.yml');

let pass = 0;
let fail = 0;
const ok = (m) => {
  console.log(`  PASS ${m}`);
  pass++;
};
const bad = (m) => {
  console.error(`  FAIL ${m}`);
  fail++;
};

console.log('==========================================');
console.log('  versioned manifests are stamped (#4038)');
console.log('==========================================');

/**
 * The drift roster, read from ci.yml rather than hardcoded.
 *
 * Hardcoding it here would let the two drift apart, which is the same defect
 * one level up: this test would keep passing while guarding a roster that no
 * longer exists.
 */
const ciText = readFileSync(CI, 'utf8');
const rosterLine = /GENERATED=\(([^)]*)\)/.exec(ciText);
if (!rosterLine) {
  bad('could not read the GENERATED roster from ci.yml (did it move or get renamed?)');
} else {
  ok('read the build-drift roster from ci.yml');
}
const rosterRaw = rosterLine ? rosterLine[1].split(/\s+/).filter(Boolean) : [];
const includes = rosterRaw.filter((p) => !p.startsWith("':!")).map((p) => p.replace(/^'|'$/g, ''));
const excludes = rosterRaw
  .filter((p) => p.startsWith("':!"))
  .map((p) => p.replace(/^':!/, '').replace(/'$/, ''));

const inRoster = (file) =>
  includes.some((i) => file === i || file.startsWith(i)) &&
  !excludes.some((e) => file === e || file.startsWith(e));

/**
 * Scope: files named `plugin.json`, nothing else.
 *
 * The first draft of this test scanned every tracked JSON carrying a top-level
 * `version` and reported 119 offenders, which is a checker that would be
 * switched off within a day. Most of them are per-skill `metadata.json` and
 * `test-cases.json` files whose `version` is the SKILL's own and has no
 * relationship to the project version. `plugins/ork/hooks/package.json` is at
 * 1.0.0 for the same reason.
 *
 * A plugin manifest is different: its version is what a HOST reads to decide
 * what it installed, so it is the one that has to track the release. That is
 * the defect in #4038, and widening past it only adds noise.
 */
const tracked = execFileSync('git', ['ls-files', '*plugin.json'], { cwd: REPO_ROOT, encoding: 'utf8' })
  .split('\n')
  .filter((f) => f && !f.includes('node_modules'))
  .filter((f) => f.split('/').pop() === 'plugin.json');

const versioned = [];
for (const f of tracked) {
  let parsed;
  try {
    parsed = JSON.parse(readFileSync(join(REPO_ROOT, f), 'utf8'));
  } catch {
    continue; // not our business here; JSON syntax has its own gate
  }
  if (parsed && typeof parsed === 'object' && typeof parsed.version === 'string') {
    versioned.push(f);
  }
}

const config = JSON.parse(readFileSync(CONFIG, 'utf8'));
const stamped = new Set();
const walk = (node) => {
  if (Array.isArray(node)) return node.forEach(walk);
  if (node && typeof node === 'object') {
    if (Array.isArray(node['extra-files'])) {
      for (const e of node['extra-files']) stamped.add(typeof e === 'string' ? e : e.path);
    }
    Object.values(node).forEach(walk);
  }
};
walk(config);

// Anti-vacuity: if either side comes back empty the comparison below is
// trivially satisfied and proves nothing. Both have been non-empty since this
// repo had a release, so an empty one means a selector broke, not that the
// work is done.
if (versioned.length === 0) bad('found no versioned tracked manifests, the scan is broken');
else ok(`scanned ${versioned.length} versioned plugin manifest(s)`);
if (stamped.size === 0) bad('found no extra-files entries, the config selector is broken');
else ok(`read ${stamped.size} extra-files entry(ies)`);

const offenders = versioned.filter((f) => inRoster(f) && !stamped.has(f));
if (offenders.length === 0) {
  ok('every versioned manifest inside the drift roster is stamped');
} else {
  bad(`${offenders.length} versioned manifest(s) inside the drift roster are NOT stamped:`);
  for (const f of offenders) console.error(`         ${f}`);
  console.error('');
  console.error('       Add each to "extra-files" in .release-please-config.json:');
  console.error('         { "type": "json", "path": "<path>", "jsonpath": "$.version" }');
  console.error('');
  console.error('       Without it, release-please bumps the source, the mirror regenerates');
  console.error('       from it, and every release PR fails Build on drift until the autoheal');
  console.error('       bot pushes a second commit. See #4038 and');
  console.error('       docs/audits/release-please-version-drift-2026-05-22.md');
}

// The fixture must stay OUT, and stay unstamped. If a future edit "helpfully"
// adds it, its pinned 0.0.1 becomes the project version and the canary stops
// asserting the upstream shape it exists for.
const FIXTURE = 'tests/fixtures/fn-hooks-canary/.claude-plugin/plugin.json';
if (versioned.includes(FIXTURE)) {
  if (stamped.has(FIXTURE)) {
    bad(`${FIXTURE} must NOT be stamped, its pinned version is what it asserts`);
  } else if (inRoster(FIXTURE)) {
    bad(`${FIXTURE} is inside the drift roster, which would force it to be stamped`);
  } else {
    ok('the fn-hooks canary fixture is correctly outside the roster and unstamped');
  }
}

console.log('==========================================');
console.log(`  Passed: ${pass}  Failed: ${fail}`);
console.log('==========================================');
process.exit(fail === 0 ? 0 : 1);
